        /// <summary>Convenience for Mod.GetPreloadNames(): (scene, path) for every entry in All (or a filtered subset).
        /// NOTE: preloading everything means loading ~148 scenes at startup - filter it.</summary>
        public static List<(string, string)> GetPreloadNames(System.Func<string, EnemyLocation, bool> filter = null)
        {
            var list = new List<(string, string)>();
            foreach (var kv in All)
                if (filter == null || filter(kv.Key, kv.Value)) list.Add((kv.Value.Scene, kv.Value.Path));
            return list;
        }
